import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.2Gs1zKBA.js";const m=JSON.parse('{"title":"接口总览","description":"","frontmatter":{},"headers":[],"relativePath":"motion/index.md","filePath":"motion/index.md","lastUpdated":1794555138000}'),r={name:"motion/index.md"};function a(i,d,n,s,l,p){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="接口总览" tabindex="-1">接口总览 <a class="header-anchor" href="#接口总览" aria-label="Permalink to &quot;接口总览&quot;">​</a></h1><p>Onero A1 的运动接口主要按“目标是什么”和“由谁推进控制循环”选择：SDK 可以完成整段目标或速度运动，应用也可以通过单帧接口自行驱动实时循环。</p><h2 id="如何选择接口" tabindex="-1">如何选择接口 <a class="header-anchor" href="#如何选择接口" aria-label="Permalink to &quot;如何选择接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务要求</th><th>推荐接口</th><th>关键区别</th></tr></thead><tbody><tr><td>返回软件定义的关节零位</td><td><code>home()</code></td><td>本质上是预设零位目标的关节运动</td></tr><tr><td>到达指定关节角</td><td><code>movej()</code></td><td>约束关节目标，不保证 TCP 走直线</td></tr><tr><td>到达指定 TCP 位姿，不要求直线路径</td><td><code>movep()</code></td><td>先求终点 IK，再进行关节插值</td></tr><tr><td>TCP 沿直线运动</td><td><code>movel()</code></td><td>对完整直线路径逐点求解 IK</td></tr><tr><td>TCP 沿圆弧运动</td><td><code>movec()</code></td><td>由当前位置、经过点和终点定义圆弧</td></tr><tr><td>外部控制器逐帧生成目标</td><td><code>servoj()</code>、<code>servop()</code></td><td>每次调用只发送一帧，应用负责循环频率和超时</td></tr><tr><td>按关节速度或 TCP 速度运动一段时间</td><td><code>speedj()</code>、<code>speedl()</code></td><td>SDK 完成加速、保持和减速，调用期间阻塞</td></tr><tr><td>中断当前运动并减速到零</td><td><code>stop()</code></td><td>停止后保持当前位置，机械臂仍然使能</td></tr></tbody></table><h2 id="参数与执行特性" tabindex="-1">参数与执行特性 <a class="header-anchor" href="#参数与执行特性" aria-label="Permalink to &quot;参数与执行特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>核心输入</th><th>时间与速度参数</th><th>调用与返回</th></tr></thead><tbody><tr><td><code>home()</code></td><td>无显式目标</td><td><code>duration</code>，可选 <code>kp</code>、<code>kd</code></td><td>调用一次，运动结束后返回</td></tr><tr><td><code>movej()</code></td><td><code>joints</code>：7 个关节角，单位 rad</td><td><code>duration</code>， <code>speed</code>与 <code>acceleration</code></td><td>调用一次，运动结束后返回</td></tr><tr><td><code>movep()</code></td><td><code>position</code>、<code>rotation</code>、<code>frame</code></td><td><code>duration</code>， <code>speed</code>与 <code>acceleration</code></td><td>调用一次，运动结束后返回</td></tr><tr><td><code>movel()</code>、<code>movec()</code></td><td>TCP 位置、姿态和 <code>frame</code></td><td><code>duration</code>， <code>speed</code>与 <code>acceleration</code></td><td>先检查路径 IK，再执行并阻塞到结束</td></tr><tr><td><code>servoj()</code></td><td><code>joints</code>，可选 <code>velocities</code>、<code>kp</code>、<code>kd</code>、<code>tau_ff</code></td><td>没有 <code>duration</code></td><td>应用按 <code>arm.control_freq</code> 持续调用</td></tr><tr><td><code>servop()</code></td><td><code>position</code>、<code>rotation</code>、<code>frame</code>，可选 <code>kp</code>、<code>kd</code></td><td>没有 <code>duration</code></td><td>应用按 <code>arm.control_freq</code> 持续调用</td></tr><tr><td><code>speedj()</code></td><td>7 个关节速度，单位 rad/s</td><td><code>acceleration</code>、<code>duration</code></td><td>调用一次，减速到零后返回</td></tr><tr><td><code>speedl()</code></td><td><code>[vx, vy, vz, wx, wy, wz]</code>，单位 m/s、rad/s</td><td><code>acceleration</code> 、<code>duration</code></td><td>调用一次，减速到零后返回</td></tr><tr><td><code>stop()</code></td><td>无运动目标</td><td><code>deceleration</code></td><td>可从另一线程中断运动；停止后返回</td></tr></tbody></table><p>使用这些参数时需要注意：</p><ul><li>目标运动同时传入 <code>duration</code> 和 <code>speed</code> 时，<code>duration</code> 优先；建议只选择一种时间约束。</li><li><code>speedj()</code>、<code>speedl()</code> 未传 <code>duration</code> 时，默认在加速后保持目标速度 1 秒，再减速到零。</li><li><code>servoj()</code>、<code>servop()</code> 停止发送新帧不等于执行受控停止；循环退出时必须显式设计 <code>stop()</code> 或应用层安全策略。</li><li>阻塞式调用返回表示该运动过程已经结束，不代表实际位置与理想目标完全一致；应检查返回的 <code>ArmState</code>、<code>get_state()</code> 或 <code>get_pose()</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">真机发送目标前</p><p>核对机械臂型号、坐标系、TCP 和负载，检查起点到终点的完整路径，并提前确定数据中断或目标不可达时的停止方式。首次验证应先在 MuJoCo 中确认方向和路径，再使用小幅、低速真机目标。</p></div><p>更详细的接口说明见<a href="/onerobot-A1/motion/basic">关节与笛卡尔运动</a>和<a href="/onerobot-A1/motion/realtime">实时与速度控制</a>，视频与完整代码见<a href="/onerobot-A1/use-cases/motion-control">使用案例：运动控制</a>。</p>',10)])])}const u=t(r,[["render",a]]);export{m as __pageData,u as default};
